def count_unique_words(text):
    words = text.split()
    return len(set(words))

def words_appearing_once(text):
    words = text.split()
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sorted([w for w, c in counts.items() if c == 1])

def words_appearing_at_least(text, k):
    words = text.split()
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sorted([w for w, c in counts.items() if c >= k])

def most_common_first_occurrence(items):
    counts = {}
    for x in items:
        counts[x] = counts.get(x, 0) + 1
    best = None
    best_count = -1
    for x in items:
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

def count_words_case_insensitive(text):
    words = text.split()
    counts = {}
    for w in words:
        lw = w.lower()
        counts[lw] = counts.get(lw, 0) + 1
    return counts

def dict_merge_multiple(dicts):
    result = {}
    for d in dicts:
        for k, v in d.items():
            result[k] = result.get(k, 0) + v
    return result

def distinct_items_per_group(pairs):
    groups = {}
    for g, item in pairs:
        groups.setdefault(g, set()).add(item)
    return {g: len(items) for g, items in groups.items()}

def nested_group_counts(pairs):
    result = {}
    for g, item in pairs:
        if g not in result:
            result[g] = {}
        result[g][item] = result[g].get(item, 0) + 1
    return result

def lookup_chain(d, keys):
    current = d
    for k in keys:
        if not isinstance(current, dict) or k not in current:
            return None
        current = current[k]
    return current

def count_leaf_values(nested):
    count = 0
    for v in nested.values():
        if isinstance(v, dict):
            count += count_leaf_values(v)
        else:
            count += 1
    return count

def flatten_nested_dict(nested):
    result = {}

    def helper(d, prefix):
        for k, v in d.items():
            key = f"{prefix}.{k}" if prefix else str(k)
            if isinstance(v, dict):
                helper(v, key)
            else:
                result[key] = v

    helper(nested, "")
    return result

def merge_char_frequencies(strings):
    result = {}
    for s in strings:
        for c in s:
            result[c] = result.get(c, 0) + 1
    return result

def top_k_keys_by_value(d, k):
    items = sorted(d.items(), key=lambda kv: (-kv[1], kv[0]))
    return [key for key, val in items][:k]

def bottom_k_keys_by_value(d, k):
    items = sorted(d.items(), key=lambda kv: (kv[1], kv[0]))
    return [key for key, val in items][:k]

def count_items_by_category(items, categories):
    result = {}
    for item in items:
        cat = categories.get(item, 'other')
        result[cat] = result.get(cat, 0) + 1
    return result

def build_multimap(pairs):
    groups = {}
    for k, v in pairs:
        groups.setdefault(k, set()).add(v)
    return {k: sorted(vs) for k, vs in groups.items()}

def count_values_across_multimap(d):
    result = {}
    for values in d.values():
        for v in values:
            result[v] = result.get(v, 0) + 1
    return result

def unique_words_first_only(text1, text2):
    words1 = set(text1.split())
    words2 = set(text2.split())
    return sorted(words1 - words2)

def word_count_difference(text1, text2):
    from collections import Counter
    c1 = Counter(text1.split())
    c2 = Counter(text2.split())
    words = set(c1) | set(c2)
    return {w: c1.get(w, 0) - c2.get(w, 0) for w in words}
